from common import *
from phase2_temporal import ema
import pandas as pd,hashlib
O=ROOT/"phase97";assert (O/"complete.json").exists();pr=json.loads((O/"protocol.json").read_text());assert hashlib.sha256((O/"protocol.json").read_bytes()).hexdigest()==(O/"protocol.sha256").read_text();assert json.loads((O/"prediction_audit.json").read_text())["status"]=="PASS"
for spec in pr["models"]:assert hashlib.sha256(Path(spec["path"]).read_bytes()).hexdigest()==spec["sha256"]
assert hashlib.sha256((ROOT/"phase95/participants.csv").read_bytes()).hexdigest()==pr["seed17_metrics_sha256"]
rows=[];stages=[]
for c in pr["cases"]:
 name="_".join(c[k] for k in ["domain","subject","montage"]);data=np.load(O/"predictions"/(name+".npz"));assert len(data.files)==12;yy=np.load(c["labels"]);y=yy["y"] if c["labels"].endswith(".npz") else yy
 for key in data.files:
  method,seed=key.rsplit("_seed",1);p=data[key];assert p.shape==(len(y),5) and np.isfinite(p).all()
  for alpha in pr["ema"]:
   q=p if alpha==1 else ema(p,alpha);mm=metrics(y,q);cm=np.array(mm["confusion"]);rows.append(dict(domain=c["domain"],subject=c["subject"],montage=c["montage"],method=method,seed=int(seed),ema=alpha,macro_f1=100*mm["macro_f1"],accuracy=100*cm.trace()/cm.sum(),ce=mm["ce"],balanced_accuracy=100*mm["balanced_accuracy"]))
   for k,stage in enumerate(["W","N1","N2","N3","REM"]):stages.append(dict(domain=c["domain"],subject=c["subject"],montage=c["montage"],method=method,seed=int(seed),ema=alpha,stage=stage,f1=200*cm[k,k]/max(cm[k].sum()+cm[:,k].sum(),1),recall=100*cm[k,k]/max(cm[k].sum(),1),true_windows=int(cm[k].sum()),predicted_windows=int(cm[:,k].sum())))
new=pd.DataFrame(rows);assert len(new)==3168;old=pd.read_csv(ROOT/"phase95/participants.csv");old["seed"]=17;df=pd.concat([old,new],ignore_index=True);assert len(df)==4752;keys=["domain","subject","montage","method","ema"];assert (df.groupby(keys).seed.nunique()==3).all();df.to_csv(O/"participants.csv",index=False);person=df.groupby(keys)[["macro_f1","accuracy","ce","balanced_accuracy"]].mean().reset_index();person.to_csv(O/"seedmean_people.csv",index=False);summary=person.groupby(["domain","montage","method","ema"])[["macro_f1","accuracy","ce","balanced_accuracy"]].mean();summary.to_csv(O/"summary.csv");df.groupby(["domain","montage","method","seed","ema"]).macro_f1.mean().to_csv(O/"seed_summary.csv")
comp=[];rng=np.random.default_rng(97017);pairs=[("amplitude_augmented_selected","repeat_raw_selected","primary_source_selected"),("amplitude_augmented_final5","repeat_raw_final5","secondary_fixed5epochs"),("amplitude_augmented_selected","initial_guarded_median","secondary_vs_input_guard"),("amplitude_augmented_selected","initial_floor","secondary_vs_input_floor")]
for (domain,montage,alpha),g in person.groupby(["domain","montage","ema"]):
 p=g.pivot(index="subject",columns="method",values="macro_f1");idx=rng.integers(0,len(p),(10000,len(p)))
 for newmethod,oldmethod,label in pairs:
  v=p[newmethod]-p[oldmethod];ci=np.quantile(v.to_numpy()[idx].mean(1),[.025,.975]);comp.append(dict(domain=domain,montage=montage,ema=alpha,comparison=label,people=len(v),new_f1=p[newmethod].mean(),old_f1=p[oldmethod].mean(),difference_pp=v.mean(),ci_low=ci[0],ci_high=ci[1],positive_people=int((v>0).sum()),harm_over_1pp=int((v< -1).sum()),worst_pp=v.min()))
comp=pd.DataFrame(comp);comp.to_csv(O/"paired_comparisons.csv",index=False);primary=comp[(comp.comparison=="primary_source_selected")&(comp.ema==.5)&comp.montage.isin(["native","left"])];primary.to_csv(O/"primary_results.csv",index=False)
stold=pd.read_csv(ROOT/"phase95/stage_participants.csv");stold["seed"]=17;st=pd.concat([stold,pd.DataFrame(stages)],ignore_index=True);st.to_csv(O/"stage_participants.csv",index=False);sp=st.groupby(keys+["stage"])[["f1","recall","true_windows","predicted_windows"]].mean().reset_index();sp.groupby(["domain","montage","method","ema","stage"]).agg(f1=("f1","mean"),recall=("recall","mean"),true_windows=("true_windows","sum"),predicted_windows=("predicted_windows","sum"),people_with_stage=("true_windows",lambda v:int((v>0).sum()))).to_csv(O/"stage_summary.csv")
audit=dict(status="PASS",total_method_streams=4752,new_streams_recomputed=3168,classifier_seeds=[17,29,43],within_person_seed_metric_averaging=True,no_probability_ensemble=True,no_seed_pseudoreplication=True,seed29_source_guard_fallback_retained=True,no_target_checkpointselection=True,all_targets_previously_observed=True,no_online_updates=True,not_blind_replication=True);(O/"audit.json").write_text(json.dumps(audit,indent=2))
(O/"report.html").write_text('<!doctype html><meta charset="utf-8"><style>body{font:16px/1.6 sans-serif;max-width:1450px;margin:35px auto}td,th{padding:6px;border:1px solid #ddd}</style><h1>静态源幅值增强：三个分类器种子的完整复核</h1><p>固定源方法在seed17/29/43分别执行，相同的源原幅值保护条件和三幅值选择规则。seed29未满足条件，增强分支按规则退回初始模型，仍纳入全部汇总。先在人内平均三个种子的指标，再按受试者配对估计区间；未合并概率，也未把种子当作新增独立受试者。</p><p>全部目标人群此前已观察，方法设计受既有幅值问题启发；这是探索性复核，不替换phase83的独立患者原定主比较。单种子阶段的数据不用于修改另外两种子的源训练规则。</p>'+primary.to_html(index=False,float_format=lambda v:f"{v:.6f}")+'<h2>同EMA0.5的全部比较</h2>'+comp[comp.ema==.5].to_html(index=False,float_format=lambda v:f"{v:.6f}")+'<h2>绝对结果</h2>'+summary.reset_index().query("ema==.5").to_html(index=False,float_format=lambda v:f"{v:.6f}")+'<p>源选定检查点可能有不同有效训练轮数；固定第5轮配对单独报告相同实际更新预算下的结果，属于诊断对照，不从目标表现中选模型。区间仅反映给定三种子和既有受试者样本的不确定性。输入处理和模型均未进行测试时梯度更新。</p><p><a href="audit.json">三种子汇总审计</a> · <a href="seed_summary.csv">每个种子的结果</a> · <a href="../phase94/report.html">seed17源选择</a> · <a href="../phase96/seed29/report.html">seed29源选择</a> · <a href="../phase96/seed43/report.html">seed43源选择</a> · <a href="../phase83/report.html">保留原患者主结果</a></p>')
